mapper.select:
select doctor.*, department.name as departmentName,hospital.hospital_name as hospitalName
from doctor
left join department on doctor.department_id = department.id
left join plan on plan.doctor_id = doctor.id
left join hospital on doctor.hospital_id = hospital.id

    and id= #{id}
    and username like concat('%', #{username}, '%')
    and password= #{password}
    and name= #{name}
    and phone= #{phone}
    and email= #{email}
    and avatar= #{avatar}
    and role= #{role}
    and department_id = #{departmentId}
    and plan.week = #{week}
    and doctor.hospital_id = #{hospitalId}

SELECT doctor.*, hospital_name, department.name, plan.num
FROM doctor, hospital, department, plan
WHERE doctor.hospital_id = #{hospitalId}
  AND doctor.department_id = #{departmentId}
  AND doctor.id = plan.doctor_id
  AND plan.date = #{selectedDate}
  AND doctor.hospital_id = hospital.id
  AND doctor.department_id = department.id
